}
pages.each do |name, (title, heading, message)|
  path = "/app/public/#{name}.html"
  html = File.read(path)
  html.sub!(%r{<title>(.*?)</title>}) { "<title>#{$1} / #{title}</title>" }
  html.sub!(%r{^(\s*)<h2>(.*?)</h2>\n}) { "#{$1}<h2>#{$2}</h2>\n#{$1}<h2 lang=\"ja\">#{heading}</h2>\n" }
  html.sub!(%r{^(\s*)<div>(.*?)</div>\n}) { "#{$1}<div>#{$2}</div>\n#{$1}<div lang=\"ja\">#{message}</div>\n" }
  html.sub!(%r{<a href="/">&larr; Back home</a>}) { %(<a href="/">&larr; Back home <span lang="ja">／ ホームに戻る</span></a>) }
  File.write(path, html)
end
EOF
