arguments.command:
cd /app && cat > tmp/check_t_calls.rb <<'EOF'
require "yaml"
def load(locale)
  tree = {}
  deep = ->(a, b) { a.merge(b) { |_, x, y| x.is_a?(Hash) && y.is_a?(Hash) ? deep.(x, y) : y } }
  Dir["/app/config/locales/**/*.yml", "/app/saas/config/locales/**/*.yml"].each { |f| tree = deep.(tree, YAML.load_file(f)[locale] || {}) }
  tree
end
TREES = { "en" => load("en"), "ja" => load("ja") }
def exists?(locale, key)
  node = TREES[locale]
  key.split(".").each { |k| return false unless node.is_a?(Hash) && node.key?(k); node = node[k] }
  true
end
missing = []
files = Dir["/app/app/{views,helpers,models,controllers,mailers}/**/*.{erb,rb}", "/app/saas/app/**/*.{erb,rb}", "/app/lib/**/*.rb"]
files.each do |f|
  src = File.read(f)
  src.scan(/\b(?:t|I18n\.t|translate)\(?\s*["']([.\w]+)["']/).flatten.each do |key|
    if key.start_with?(".")
      if f =~ %r{/views/}
        vp = f.sub(%r{.*/app/views/(mailers/)?}, "").sub(/\..*\z/, "").sub(%r{/_([^/]+)\z}, '/\1')
        full = vp.tr("/", ".") + key
      elsif f =~ %r{/mailers/}
        next # lazy keys in mailers depend on the action; checked by tests
      elsif f =~ %r{/controllers/}
        next
      else
        next
      end
    else
      full = key
    end
    next if full.start_with?("javascript") && false
    %w[en ja].each { |l| missing << "#{l}: #{full}  (#{f.sub('/app/', '')})" unless exists?(l, full) || (f.include?("/saas/") && false) }
  end
end
puts missing.uniq
EOF
ruby tmp/check_t_calls.rb

